-- What supabase/talk_asks.sql does, tried inside the rolled-back transaction
-- of a dry run: nothing here is kept. Made-up accounts, made and gone with
-- the transaction: Ada, Bo, Cy and Dee at Resend's test addresses (the
-- checks' pool), Eve at example.com (anybody else) and Kit, who said under 13.
--
--   set -a; . ./.env; set +a
--   PG_MODULE=/tmp/pg/node_modules/pg/lib/index.js \
--     node tools/apply_sql.mjs supabase/talk_asks.sql --dry --try=tools/talk_asks_try.sql --table=talk_threads
--
-- Each statement is on one line: the dry run splits at a semicolon that
-- ends a line.
create function pg_temp.tries(statement text) returns text language plpgsql as $$ begin execute statement; return 'allowed'; exception when others then return 'refused: ' || sqlerrm; end $$;
grant execute on function pg_temp.tries(text) to anon, authenticated, service_role;
-- The columns are new and empty; the functions the server's alone.
select (select count(*) from public.talk_threads where ask_version is not null) as asks, (select count(*) from public.talk_posts where pin is not null) as pinned_posts;
select p.proname, has_function_privilege('anon', p.oid, 'execute') as anon, has_function_privilege('authenticated', p.oid, 'execute') as signed_in, has_function_privilege('service_role', p.oid, 'execute') as server, p.prosecdef as security_definer from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('talk_parts_shaped', 'talk_ask', 'talk_pin_reply', 'talk_ask_as', 'talk_asks_of', 'talk_pins_of', 'talk_asks_on') order by p.proname;
-- The made-up six, and Ada's model with two versions.
insert into auth.users (id, instance_id, aud, role, email, created_at, email_confirmed_at) values ('00000000-0000-4000-8000-0000000fb001', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'ask-try-ada@resend.dev', now() - interval '30 days', now()), ('00000000-0000-4000-8000-0000000fb002', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'ask-try-bo@resend.dev', now() - interval '30 days', now()), ('00000000-0000-4000-8000-0000000fb003', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'ask-try-cy@resend.dev', now() - interval '30 days', now()), ('00000000-0000-4000-8000-0000000fb004', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'ask-try-dee@resend.dev', now() - interval '30 days', now()), ('00000000-0000-4000-8000-0000000fb005', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'ask-try-eve@example.com', now() - interval '30 days', now()), ('00000000-0000-4000-8000-0000000fb006', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'ask-try-kit@resend.dev', now() - interval '30 days', now());
select public.answer_age('00000000-0000-4000-8000-0000000fb001', true)->>'over_13' as ada, public.answer_age('00000000-0000-4000-8000-0000000fb002', true)->>'over_13' as bo, public.answer_age('00000000-0000-4000-8000-0000000fb003', true)->>'over_13' as cy, public.answer_age('00000000-0000-4000-8000-0000000fb004', true)->>'over_13' as dee, public.answer_age('00000000-0000-4000-8000-0000000fb005', true)->>'over_13' as eve, public.answer_age('00000000-0000-4000-8000-0000000fb006', false)->>'over_13' as kit;
insert into public.people (account, handle, name) values ('00000000-0000-4000-8000-0000000fb001', 'ask-try-ada', 'Ada Try'), ('00000000-0000-4000-8000-0000000fb002', 'ask-try-bo', 'Bo Try'), ('00000000-0000-4000-8000-0000000fb003', 'ask-try-cy', 'Cy Try'), ('00000000-0000-4000-8000-0000000fb004', 'ask-try-dee', 'Dee Try'), ('00000000-0000-4000-8000-0000000fb005', 'ask-try-eve', 'Eve Try');
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, test, created_at, has_image) values ('AskTry0001', '00000000-0000-4000-8000-0000000fb001', 'Try windmill', 'Ada Try', 40, 100, false, true, now(), false), ('AskTry0002', '00000000-0000-4000-8000-0000000fb006', 'Try kite', null, 10, 100, false, true, now(), false);
insert into public.share_versions (model, n, at, parts, bytes, has_image) values ('AskTry0001', 1, now() - interval '1 day', 40, 100, false), ('AskTry0001', 2, now(), 44, 110, false), ('AskTry0002', 1, now(), 10, 100, false);
-- A page's keys are refused, signed out and signed in.
set local role anon;
select pg_temp.tries($q$select public.talk_ask('00000000-0000-4000-8000-0000000fb001', 'AskTry0001', 2, 3, null, 'Forged', 'As Ada')$q$) as anon_asks_as_ada, pg_temp.tries($q$select public.talk_asks_on('AskTry0001', '00000000-0000-4000-8000-0000000fb001')$q$) as anon_reads_adas_answers, pg_temp.tries($q$update public.talk_posts set pin = '{"part":"3001.dat","colour":4,"at":[0,0,0]}'$q$) as anon_pins;
reset role;
set local role authenticated;
select pg_temp.tries($q$select public.talk_pin_reply('00000000-0000-4000-8000-0000000fb002', 1, 'As Bo', '{"part":"3001.dat","colour":4,"at":[0,0,0]}')$q$) as signed_in_pins_as_bo, pg_temp.tries($q$select public.talk_pins_of(array[1]::bigint[])$q$) as signed_in_reads_pins;
reset role;
-- Ada asks about step 3 of version 2 of her windmill, with two parts picked.
create temporary table a_ask on commit drop as select public.talk_ask('00000000-0000-4000-8000-0000000fb001', 'AskTry0001', 2, 3, '[{"part":"3001.dat","colour":4,"at":[0,-24,0]},{"part":"3020.dat","colour":15,"at":[20,0,10]}]', 'How do I brace the sails?', 'The sails droop at step 3: how would you brace them?') as r;
select r->'thread'->>'board' as board, r->'thread'->>'title' as title, r->'ask'->>'model' as model, r->'ask'->>'version' as version, r->'ask'->>'step' as step, jsonb_array_length(r->'ask'->'parts') as parts, r->'ask'->>'newest' as newest, r ? 'refused' as refused from a_ask;
select t.test as test_pool, t.model is null as not_show_and_tell, t.ask_model, t.ask_version, t.ask_step from public.talk_threads t where t.id = (select (r->'thread'->>'id')::bigint from a_ask);
-- What is refused: Bo asks about Ada's model; a version that is not there; a step past the end; too many parts; a part that is no place; Kit, under 13, about her own; nobody signed in.
select public.talk_ask('00000000-0000-4000-8000-0000000fb002', 'AskTry0001', 2, 3, null, 'Not my model', 'Asked about Ada''s')->>'refused' as bo_asks_adas, public.talk_ask('00000000-0000-4000-8000-0000000fb001', 'AskTry0001', 9, 3, null, 'No such version', 'Version nine')->>'refused' as no_version, public.talk_ask('00000000-0000-4000-8000-0000000fb001', 'AskTry0001', 2, 0, null, 'Step nought', 'Step 0')->>'refused' as step_zero, public.talk_ask('00000000-0000-4000-8000-0000000fb001', 'AskTry0001', 2, 3, (select jsonb_agg(jsonb_build_object('part', '3001.dat', 'colour', 4, 'at', jsonb_build_array(g, 0, 0))) from generate_series(1, 13) g), 'Thirteen parts', 'Too many')->>'refused' as thirteen_parts, public.talk_ask('00000000-0000-4000-8000-0000000fb001', 'AskTry0001', 2, 3, '[{"part":"3001.dat"}]', 'No place', 'Part without a place')->>'refused' as no_place, public.talk_ask('00000000-0000-4000-8000-0000000fb006', 'AskTry0002', 1, 1, null, 'Kit asks', 'Under thirteen')->>'refused' as kit_under_13, public.talk_ask(null, 'AskTry0001', 2, 3, null, 'Nobody', 'Signed out')->>'refused' as nobody;
-- Bo answers on a part; Cy answers in words; Eve (the people's pool) cannot reply in a check's thread.
create temporary table a_bo on commit drop as select public.talk_pin_reply('00000000-0000-4000-8000-0000000fb002', (select (r->'thread'->>'id')::bigint from a_ask), 'Brace it here with a 1 x 4 plate under the hub.', '{"part":"3001.dat","colour":4,"at":[0,-24,0],"near":[],"full":true}') as r;
select r->'post'->>'by' as by, r->'post'->'pin'->>'part' as on_part, r ? 'refused' as refused from a_bo;
select public.talk_reply('00000000-0000-4000-8000-0000000fb003', (select (r->'thread'->>'id')::bigint from a_ask), 'A Technic pin would hold it too.')->'post'->>'by' as cy_words, public.talk_pin_reply('00000000-0000-4000-8000-0000000fb005', (select (r->'thread'->>'id')::bigint from a_ask), 'From the other pool', '{"part":"3001.dat","colour":4,"at":[0,0,0]}')->>'refused' as eve_other_pool, public.talk_pin_reply('00000000-0000-4000-8000-0000000fb002', (select (r->'thread'->>'id')::bigint from a_ask), 'No place', '{"part":"3001.dat"}')->>'refused' as no_place, public.talk_pin_reply('00000000-0000-4000-8000-0000000fb002', 999999999, 'Nowhere', '{"part":"3001.dat","colour":4,"at":[0,0,0]}')->>'refused' as no_thread;
-- A pin only in an ask's thread: Bo's own Help thread with no ask takes none.
create temporary table a_plain on commit drop as select public.talk_start('00000000-0000-4000-8000-0000000fb002', 'help', 'A plain question', 'Which glue is best? (none)') as r;
select public.talk_pin_reply('00000000-0000-4000-8000-0000000fb003', (select (r->'thread'->>'id')::bigint from a_plain), 'On a part', '{"part":"3001.dat","colour":4,"at":[0,0,0]}')->>'refused' as plain_thread, pg_temp.tries($q$update public.talk_posts set pin = '{"part":"3001.dat","colour":4,"at":[0,0,0]}' where first$q$) as pin_on_a_first_post;
-- Ada's studio asks: her ask, Bo's answer on its part, not Cy's words. Bo asking for Ada's model's asks gets nothing.
select jsonb_array_length(public.talk_asks_on('AskTry0001', '00000000-0000-4000-8000-0000000fb001')) as adas_asks, jsonb_array_length(public.talk_asks_on('AskTry0001', '00000000-0000-4000-8000-0000000fb001')->0->'answers') as answers_on_parts, public.talk_asks_on('AskTry0001', '00000000-0000-4000-8000-0000000fb001')->0->'answers'->0->>'handle' as by, public.talk_asks_on('AskTry0001', '00000000-0000-4000-8000-0000000fb001')->0->'answers'->0->'pin'->>'part' as part, public.talk_asks_on('AskTry0001', '00000000-0000-4000-8000-0000000fb002') is null as bo_gets_none;
-- The thread's page: its ask and its pins, by thread and post.
select public.talk_asks_of(array[(select (r->'thread'->>'id')::bigint from a_ask), (select (r->'thread'->>'id')::bigint from a_plain)])->0->'ask'->>'step' as asked_step, jsonb_array_length(public.talk_asks_of(array[(select (r->'thread'->>'id')::bigint from a_ask), (select (r->'thread'->>'id')::bigint from a_plain)])) as asks_among_two, public.talk_pins_of(array[(select (r->'post'->>'id')::bigint from a_bo)])->0->'pin'->>'part' as pinned_part;
-- Blocks hold: Ada blocks Dee; Dee cannot answer on a part in her thread. Ada blocks Bo: his answer leaves her studio's list.
insert into public.blocks (blocker, blocked) values ('00000000-0000-4000-8000-0000000fb001', '00000000-0000-4000-8000-0000000fb004');
select public.talk_pin_reply('00000000-0000-4000-8000-0000000fb004', (select (r->'thread'->>'id')::bigint from a_ask), 'Blocked answer', '{"part":"3001.dat","colour":4,"at":[0,0,0]}')->>'refused' as dee_blocked;
insert into public.blocks (blocker, blocked) values ('00000000-0000-4000-8000-0000000fb001', '00000000-0000-4000-8000-0000000fb002');
select jsonb_array_length(public.talk_asks_on('AskTry0001', '00000000-0000-4000-8000-0000000fb001')->0->'answers') as answers_after_blocking_bo;
delete from public.blocks where blocker = '00000000-0000-4000-8000-0000000fb001' and blocked = '00000000-0000-4000-8000-0000000fb002';
-- Reports hold: the owner hides Bo's answer; it leaves the studio's list.
update public.talk_posts set hidden_at = now(), hidden_by = 'admin' where id = (select (r->'post'->>'id')::bigint from a_bo);
select jsonb_array_length(public.talk_asks_on('AskTry0001', '00000000-0000-4000-8000-0000000fb001')->0->'answers') as answers_after_hiding;
-- The model gone: the thread stays, said as an ask with no model.
delete from public.shared_models where id = 'AskTry0001';
select t.ask_model is null as model_gone, t.ask_version as still_asked_at, public.talk_ask_as(t)->>'model' is null as said_without_model from public.talk_threads t where t.id = (select (r->'thread'->>'id')::bigint from a_ask);
